import { useEffect } from "react";
import { useLocation } from "react-router-dom";
import { useSeoSettings, useSeoPages } from "@/hooks/useSeoSettings";

/**
 * Dynamic SEO head manager.
 * Updates document meta tags based on admin-configured SEO settings.
 * Supports per-page overrides that fall back to global settings.
 */
const SeoHead = () => {
  const location = useLocation();
  const { settings } = useSeoSettings();
  const { pages } = useSeoPages();

  useEffect(() => {
    if (!settings) return;

    const currentPage = pages.find((p) => p.page_path === location.pathname && p.is_active);

    // Resolve with per-page overrides falling back to global
    const title = currentPage?.title || settings.site_title || "Instant Resume Ranker";
    const description = currentPage?.description || settings.site_description || "";
    const keywords = currentPage?.keywords || settings.site_keywords || "";
    const robots = currentPage?.meta_robots || settings.meta_robots || "index, follow";
    // Per-page canonical is used as-is; global canonical is a base URL + current path
    const canonicalBase = (settings.canonical_url || "").replace(/\/$/, "");
    const canonical = currentPage?.canonical_url ||
      (canonicalBase ? `${canonicalBase}${location.pathname}` : "");
    const ogTitle = currentPage?.og_title || settings.og_title || title;
    const ogDescription = currentPage?.og_description || settings.og_description || description;
    const ogImage = currentPage?.og_image_url || settings.og_image_url || "";
    const ogType = settings.og_type || "website";
    const ogSiteName = settings.og_site_name || settings.site_title || "";
    const twitterCard = settings.twitter_card || "summary_large_image";
    const twitterSite = settings.twitter_site || "";
    const twitterCreator = settings.twitter_creator || "";
    const twitterImage = settings.twitter_image_url || ogImage;

    // Update document title
    document.title = title;

    // Helper to set/remove a meta tag
    const setMeta = (attr: string, key: string, content: string) => {
      if (!content) {
        const existing = document.querySelector(`meta[${attr}="${key}"]`);
        if (existing) existing.remove();
        return;
      }
      let el = document.querySelector(`meta[${attr}="${key}"]`) as HTMLMetaElement;
      if (!el) {
        el = document.createElement("meta");
        el.setAttribute(attr, key);
        document.head.appendChild(el);
      }
      el.setAttribute("content", content);
    };

    // Standard meta
    setMeta("name", "description", description);
    setMeta("name", "keywords", keywords);
    setMeta("name", "robots", robots);
    setMeta("name", "theme-color", settings.theme_color || "");

    // Bot-specific meta
    if (settings.googlebot) setMeta("name", "googlebot", settings.googlebot);
    if (settings.bingbot) setMeta("name", "bingbot", settings.bingbot);

    // Verification meta
    if (settings.google_search_console_id) setMeta("name", "google-site-verification", settings.google_search_console_id);
    if (settings.bing_webmaster_id) setMeta("name", "msvalidate.01", settings.bing_webmaster_id);

    // Open Graph
    setMeta("property", "og:title", ogTitle);
    setMeta("property", "og:description", ogDescription);
    setMeta("property", "og:image", ogImage);
    setMeta("property", "og:type", ogType);
    setMeta("property", "og:site_name", ogSiteName);
    if (canonical) setMeta("property", "og:url", canonical);
    if (settings.facebook_app_id) setMeta("property", "fb:app_id", settings.facebook_app_id);

    // Twitter Card
    setMeta("name", "twitter:card", twitterCard);
    setMeta("name", "twitter:title", ogTitle);
    setMeta("name", "twitter:description", ogDescription);
    setMeta("name", "twitter:image", twitterImage);
    if (twitterSite) setMeta("name", "twitter:site", twitterSite);
    if (twitterCreator) setMeta("name", "twitter:creator", twitterCreator);

    // Sitemap link (always points to /sitemap.xml on the same domain)
    if (!document.querySelector('link[rel="sitemap"]')) {
      const linkSitemap = document.createElement("link");
      linkSitemap.setAttribute("rel", "sitemap");
      linkSitemap.setAttribute("type", "application/xml");
      linkSitemap.setAttribute("title", "Sitemap");
      linkSitemap.setAttribute("href", "/sitemap.xml");
      document.head.appendChild(linkSitemap);
    }

    // Canonical link
    let linkCanonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
    if (canonical) {
      if (!linkCanonical) {
        linkCanonical = document.createElement("link");
        linkCanonical.setAttribute("rel", "canonical");
        document.head.appendChild(linkCanonical);
      }
      linkCanonical.setAttribute("href", canonical);
    } else if (linkCanonical) {
      linkCanonical.remove();
    }

    // Structured Data (JSON-LD)
    const existingLd = document.getElementById("seo-jsonld");
    if (settings.structured_data_enabled) {
      const schemas: Record<string, any>[] = [];

      // Organization schema
      const org: Record<string, any> = {
        "@context": "https://schema.org",
        "@type": "Organization",
        name: settings.organization_name || settings.site_title || "Instant Resume Ranker",
        description: settings.organization_description || description,
      };
      if (settings.organization_url) org.url = settings.organization_url;
      if (settings.organization_logo_url) org.logo = settings.organization_logo_url;
      schemas.push(org);

      // WebApplication schema
      const webapp: Record<string, any> = {
        "@context": "https://schema.org",
        "@type": "WebApplication",
        name: settings.site_title || "Instant Resume Ranker",
        description: description,
        applicationCategory: "BusinessApplication",
        operatingSystem: "Web",
      };
      if (settings.organization_url) webapp.url = settings.organization_url;
      schemas.push(webapp);

      // Per-page structured data
      if (currentPage?.structured_data_json && Object.keys(currentPage.structured_data_json).length > 0) {
        schemas.push(currentPage.structured_data_json);
      }

      const script = existingLd || document.createElement("script");
      script.setAttribute("type", "application/ld+json");
      script.id = "seo-jsonld";
      script.textContent = JSON.stringify(schemas);
      if (!existingLd) document.head.appendChild(script);
    } else if (existingLd) {
      existingLd.remove();
    }

    // ── AEO (Answer Engine Optimization) ──────────────────────────────────
    // Remove existing AEO script so it can be replaced cleanly on updates
    document.getElementById("seo-aeo-faq-jsonld")?.remove();
    if (settings.aeo_enabled) {
      const faqItems = Array.isArray(settings.aeo_faq_json) ? settings.aeo_faq_json : [];

      if (faqItems.length > 0) {
        const faqSchema = {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          mainEntity: faqItems.map((item: { q: string; a: string }) => ({
            "@type": "Question",
            name: item.q,
            acceptedAnswer: { "@type": "Answer", text: item.a },
          })),
        };
        const faqScript = document.createElement("script");
        faqScript.setAttribute("type", "application/ld+json");
        faqScript.id = "seo-aeo-faq-jsonld";
        faqScript.textContent = JSON.stringify(faqSchema);
        document.head.appendChild(faqScript);
      }

      // Re-inject the main seo-jsonld WebApplication schema with speakable if enabled
      if (settings.aeo_speakable_enabled && settings.structured_data_enabled) {
        const existingLdScript = document.getElementById("seo-jsonld");
        if (existingLdScript) {
          try {
            const schemas = JSON.parse(existingLdScript.textContent || "[]") as Record<string, any>[];
            const webappIdx = schemas.findIndex((s) => s["@type"] === "WebApplication");
            if (webappIdx !== -1) {
              schemas[webappIdx].speakable = {
                "@type": "SpeakableSpecification",
                cssSelector: ["h1", "h2", ".speakable"],
              };
              existingLdScript.textContent = JSON.stringify(schemas);
            }
          } catch {
            // JSON parse failed — leave schema as-is
          }
        }
      }
    }

    // ── GEO (Generative Engine Optimization) ──────────────────────────────
    const currentYear = new Date().getFullYear().toString();
    const siteTitle = settings.site_title || "Instant Resume Ranker";

    if (settings.geo_enabled) {
      setMeta("name", "generator", "Rankora");
      if (settings.geo_author_name) {
        setMeta("name", "citation_author", settings.geo_author_name);
      } else {
        document.querySelector('meta[name="citation_author"]')?.remove();
      }
      setMeta("name", "citation_publication_date", currentYear);
      if (settings.geo_site_description_for_ai) {
        setMeta("name", "description_ai", settings.geo_site_description_for_ai);
      } else {
        document.querySelector('meta[name="description_ai"]')?.remove();
      }
      if (settings.geo_citations_enabled) {
        setMeta("name", "citation_title", siteTitle);
        setMeta("name", "robots", "max-snippet:-1, max-image-preview:large, index, follow");
      } else {
        document.querySelector('meta[name="citation_title"]')?.remove();
      }
    } else {
      // Clean up GEO meta tags if disabled
      ["generator", "citation_author", "citation_publication_date", "description_ai", "citation_title"]
        .forEach((name) => document.querySelector(`meta[name="${name}"]`)?.remove());
    }

    // Google Analytics — reinject if ID changes or was removed
    const existingGaScript = document.getElementById("ga-script") as HTMLScriptElement | null;
    if (settings.google_analytics_id) {
      const newSrc = `https://www.googletagmanager.com/gtag/js?id=${settings.google_analytics_id}`;
      if (existingGaScript && existingGaScript.src !== newSrc) {
        // GA ID changed — remove old scripts so they get recreated
        existingGaScript.remove();
        document.getElementById("ga-init")?.remove();
      }
      if (!document.getElementById("ga-script")) {
        const gaScript = document.createElement("script");
        gaScript.id = "ga-script";
        gaScript.async = true;
        gaScript.src = newSrc;
        document.head.appendChild(gaScript);
        const gaInit = document.createElement("script");
        gaInit.id = "ga-init";
        gaInit.textContent = `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','${settings.google_analytics_id}');`;
        document.head.appendChild(gaInit);
      }
    } else {
      // GA ID cleared — clean up scripts
      document.getElementById("ga-script")?.remove();
      document.getElementById("ga-init")?.remove();
    }
  }, [settings, pages, location.pathname]);

  return null;
};

