import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { toast } from "sonner";
import { Save, Loader2, Globe } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const GlobalSeoTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const [form, setForm] = useState({
    site_title: "",
    site_description: "",
    site_keywords: "",
    canonical_url: "",
    meta_robots: "index, follow",
    theme_color: "#8b5cf6",
    google_analytics_id: "",
    google_search_console_id: "",
    bing_webmaster_id: "",
    facebook_app_id: "",
  });

  if (settings && !loaded) {
    setForm({
      site_title: settings.site_title ?? "",
      site_description: settings.site_description ?? "",
      site_keywords: settings.site_keywords ?? "",
      canonical_url: settings.canonical_url ?? "",
      meta_robots: settings.meta_robots ?? "index, follow",
      theme_color: settings.theme_color ?? "#8b5cf6",
      google_analytics_id: settings.google_analytics_id ?? "",
      google_search_console_id: settings.google_search_console_id ?? "",
      bing_webmaster_id: settings.bing_webmaster_id ?? "",
      facebook_app_id: settings.facebook_app_id ?? "",
    });
    setLoaded(true);
  }

  const save = async () => {
    if (!form.site_title.trim()) { toast.error("Site title is required"); return; }
    if (!form.site_description.trim()) { toast.error("Site description is required"); return; }
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("seo_settings")
        .update(form)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Global SEO settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "global", ...form });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2"><Globe className="h-5 w-5" /> Global Meta Tags</CardTitle>
          <CardDescription>These are the default meta tags for all pages unless overridden per-page.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2">
              <Label>Site Title</Label>
              <Input value={form.site_title} onChange={(e) => setForm({ ...form, site_title: e.target.value })} placeholder="Instant Resume Ranker" />
              <p className="text-xs text-muted-foreground mt-1">Appears in browser tab and search results</p>
            </div>
            <div className="sm:col-span-2">
              <Label>Site Description</Label>
              <Input value={form.site_description} onChange={(e) => setForm({ ...form, site_description: e.target.value })} placeholder="AI-Powered Resume Ranking..." />
              <p className="text-xs text-muted-foreground mt-1">Max 160 chars recommended. {form.site_description.length}/160</p>
            </div>
            <div className="sm:col-span-2">
              <Label>Keywords</Label>
              <Input value={form.site_keywords} onChange={(e) => setForm({ ...form, site_keywords: e.target.value })} placeholder="resume ranker, AI hiring..." />
              <p className="text-xs text-muted-foreground mt-1">Comma-separated keywords</p>
            </div>
            <div>
              <Label>Canonical URL</Label>
              <Input value={form.canonical_url} onChange={(e) => setForm({ ...form, canonical_url: e.target.value })} placeholder="https://yourdomain.com" />
            </div>
            <div>
              <Label>Meta Robots</Label>
              <Input value={form.meta_robots} onChange={(e) => setForm({ ...form, meta_robots: e.target.value })} placeholder="index, follow" />
            </div>
            <div>
              <Label>Theme Color</Label>
              <div className="flex gap-2">
                <Input type="color" value={form.theme_color} onChange={(e) => setForm({ ...form, theme_color: e.target.value })} className="w-12 h-9 p-1 cursor-pointer" />
                <Input value={form.theme_color} onChange={(e) => setForm({ ...form, theme_color: e.target.value })} className="flex-1" />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg">Analytics & Verification</CardTitle>
          <CardDescription>Search engine verification codes and analytics tracking IDs.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label>Google Analytics ID</Label>
              <Input value={form.google_analytics_id} onChange={(e) => setForm({ ...form, google_analytics_id: e.target.value })} placeholder="G-XXXXXXXXXX" />
            </div>
            <div>
              <Label>Google Search Console Verification</Label>
              <Input value={form.google_search_console_id} onChange={(e) => setForm({ ...form, google_search_console_id: e.target.value })} placeholder="verification code" />
            </div>
            <div>
              <Label>Bing Webmaster Verification</Label>
              <Input value={form.bing_webmaster_id} onChange={(e) => setForm({ ...form, bing_webmaster_id: e.target.value })} placeholder="verification code" />
            </div>
            <div>
              <Label>Facebook App ID</Label>
              <Input value={form.facebook_app_id} onChange={(e) => setForm({ ...form, facebook_app_id: e.target.value })} placeholder="App ID" />
            </div>
          </div>
        </CardContent>
