import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Save, Loader2, Mic, Bot, Plus, Trash2, Eye, EyeOff, Wand2, Copy,
  ExternalLink,
} from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

interface FaqItem {
  q: string;
  a: string;
}

// ─── FAQ Manager sub-component ────────────────────────────────────────────────

interface FaqManagerProps {
  items: FaqItem[];
  onChange: (items: FaqItem[]) => void;
}

const FaqManager = ({ items, onChange }: FaqManagerProps) => {
  const [newQ, setNewQ] = useState("");
  const [newA, setNewA] = useState("");
  const [editIndex, setEditIndex] = useState<number | null>(null);
  const [editQ, setEditQ] = useState("");
  const [editA, setEditA] = useState("");
  const [showPreview, setShowPreview] = useState(false);

  const addItem = () => {
    const q = newQ.trim();
    const a = newA.trim();
    if (!q || !a) { toast.error("Both question and answer are required"); return; }
    onChange([...items, { q, a }]);
    setNewQ("");
    setNewA("");
  };

  const deleteItem = (index: number) => {
    onChange(items.filter((_, i) => i !== index));
  };

  const startEdit = (index: number) => {
    setEditIndex(index);
    setEditQ(items[index].q);
    setEditA(items[index].a);
  };

  const saveEdit = () => {
    if (editIndex === null) return;
    const q = editQ.trim();
    const a = editA.trim();
    if (!q || !a) { toast.error("Both question and answer are required"); return; }
    const updated = items.map((item, i) => (i === editIndex ? { q, a } : item));
    onChange(updated);
    setEditIndex(null);
  };

  const cancelEdit = () => setEditIndex(null);

  const generateFaqJsonLd = () => {
    const schema = {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      mainEntity: items.map((item) => ({
        "@type": "Question",
        name: item.q,
        acceptedAnswer: { "@type": "Answer", text: item.a },
      })),
    };
    return JSON.stringify(schema, null, 2);
  };

  return (
    <div className="space-y-4">
      {/* Existing FAQ list */}
      {items.length > 0 && (
        <div className="space-y-2">
          {items.map((item, index) => (
            <div key={index} className="rounded-md border bg-muted/30 p-3 space-y-2">
              {editIndex === index ? (
                <div className="space-y-2">
                  <div>
                    <Label className="text-xs">Question</Label>
                    <Input value={editQ} onChange={(e) => setEditQ(e.target.value)} className="mt-1" />
                  </div>
                  <div>
                    <Label className="text-xs">Answer</Label>
                    <Textarea value={editA} onChange={(e) => setEditA(e.target.value)} className="mt-1 min-h-[60px]" />
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" onClick={saveEdit}>Save</Button>
                    <Button size="sm" variant="outline" onClick={cancelEdit}>Cancel</Button>
                  </div>
                </div>
              ) : (
                <div className="flex items-start gap-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate">{item.q}</p>
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{item.a}</p>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => startEdit(index)}>
                      <Wand2 className="h-3.5 w-3.5" />
                    </Button>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" onClick={() => deleteItem(index)}>
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Add new FAQ */}
      <div className="rounded-md border border-dashed p-3 space-y-3">
        <p className="text-sm font-medium text-muted-foreground">Add FAQ</p>
        <div>
          <Label className="text-xs">Question</Label>
          <Input
            value={newQ}
            onChange={(e) => setNewQ(e.target.value)}
            placeholder="What is Rankora?"
            className="mt-1"
          />
        </div>
        <div>
          <Label className="text-xs">Answer</Label>
          <Textarea
            value={newA}
            onChange={(e) => setNewA(e.target.value)}
            placeholder="Rankora is an AI-powered resume screening tool..."
            className="mt-1 min-h-[60px]"
          />
        </div>
        <Button size="sm" onClick={addItem} variant="outline">
          <Plus className="h-3.5 w-3.5 mr-1" /> Add FAQ
        </Button>
      </div>

      {/* JSON-LD preview */}
      {items.length > 0 && (
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowPreview(!showPreview)}
            className="text-xs text-muted-foreground"
          >
            {showPreview ? <EyeOff className="h-3.5 w-3.5 mr-1" /> : <Eye className="h-3.5 w-3.5 mr-1" />}
            {showPreview ? "Hide" : "Show"} FAQPage JSON-LD Preview
          </Button>
          {showPreview && (
            <pre className="mt-2 text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
              {generateFaqJsonLd()}
            </pre>
          )}
        </div>
      )}
    </div>
  );
};

