                  onCheckedChange={(v) => setForm({ ...form, aeo_speakable_enabled: v })}
                />
                <div>
                  <Label htmlFor="aeo-speakable">Enable Speakable</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Adds SpeakableSpecification to the WebApplication schema so voice assistants know which content to read aloud.
                  </p>
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-2">
                  <div>
                    <Label>FAQ Structured Data</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Q&amp;A pairs injected as FAQPage JSON-LD. Critical for Google featured snippets and AI answer engines.
                      {form.aeo_faq_json.length > 0 && (
