                  onChange={(items) => setForm({ ...form, aeo_faq_json: items })}
                />
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* ── GEO Section ──────────────────────────────────────────────────────── */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <Bot className="h-5 w-5" /> GEO — Generative Engine Optimization
            {form.geo_enabled && <Badge variant="secondary" className="text-xs">Active</Badge>}
          </CardTitle>
          <CardDescription>
            Optimize for AI-powered search engines: ChatGPT Search, Perplexity, Google SGE, and Bing Copilot.
            Controls citation meta tags, AI-readable description, and the llms.txt file for AI crawlers.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="flex items-center gap-3">
            <Switch
              id="geo-enabled"
              checked={form.geo_enabled}
              onCheckedChange={(v) => setForm({ ...form, geo_enabled: v })}
            />
            <Label htmlFor="geo-enabled">Enable GEO Optimizations</Label>
          </div>

