                  <code className="bg-muted px-1 rounded text-xs">description_ai</code> meta tag.
                </p>
                <Textarea
                  value={form.geo_site_description_for_ai}
                  onChange={(e) => setForm({ ...form, geo_site_description_for_ai: e.target.value })}
