              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Label>Author / Publisher Name</Label>
                  <Input
                    value={form.geo_author_name}
                    onChange={(e) => setForm({ ...form, geo_author_name: e.target.value })}
                    placeholder="Rankora"
                    className="mt-1"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Used in citation_author meta tag</p>
                </div>
                <div>
                  <Label>Author / Publisher URL</Label>
                  <Input
                    value={form.geo_author_url}
                    onChange={(e) => setForm({ ...form, geo_author_url: e.target.value })}
                    placeholder="https://rankora.com"
                    className="mt-1"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Used in citation_author_institution_url meta tag</p>
                </div>
              </div>

              {/* Citation meta toggle */}
              <div className="flex items-center gap-3">
                <Switch
                  id="geo-citations"
                  checked={form.geo_citations_enabled}
                  onCheckedChange={(v) => setForm({ ...form, geo_citations_enabled: v })}
                />
                <div>
                  <Label htmlFor="geo-citations">Enable Citation Meta Tags</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Adds citation_title and max-snippet:-1 robots directive so AI engines can use full snippets as citations.
                  </p>
                </div>
              </div>

              {/* llms.txt */}
              <div>
                <div className="flex items-center justify-between mb-1">
                  <div>
                    <Label>llms.txt Content</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Emerging standard for AI crawlers. Served at{" "}
                      <code className="bg-muted px-1 rounded text-xs">/llms.txt</code>{" "}
                      via the edge function below. Tells AI engines what your site does and what they may use.
                    </p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={generateDefaultLlmsTxt}
                    className="shrink-0 ml-4"
                  >
                    <Wand2 className="h-3.5 w-3.5 mr-1" /> Generate Default
                  </Button>
                </div>
                <Textarea
                  value={form.geo_llms_txt}
                  onChange={(e) => setForm({ ...form, geo_llms_txt: e.target.value })}
                  placeholder="# Rankora&#10;&#10;> AI-powered resume screening platform..."
                  className="min-h-[200px] font-mono text-sm mt-1"
                />
              </div>

              {/* llms.txt preview */}
              {form.geo_llms_txt && (
                <div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowLlmsPreview(!showLlmsPreview)}
                    className="text-xs text-muted-foreground"
                  >
                    {showLlmsPreview ? <EyeOff className="h-3.5 w-3.5 mr-1" /> : <Eye className="h-3.5 w-3.5 mr-1" />}
                    {showLlmsPreview ? "Hide" : "Show"} llms.txt Preview
                  </Button>
                  {showLlmsPreview && (
                    <pre className="mt-2 text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
                      {form.geo_llms_txt}
                    </pre>
                  )}
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Save */}
      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save AEO / GEO Settings
      </Button>

      {/* llms.txt endpoint info */}
      <Card className="border-dashed bg-muted/30">
        <CardHeader className="pb-2 pt-4">
          <CardTitle className="text-sm">llms.txt Dynamic Endpoint</CardTitle>
          <CardDescription className="text-xs">
            The llms.txt content is served live from this Supabase Edge Function URL.
            Configure a rewrite rule on your production domain so{" "}
            <code className="bg-muted px-1 rounded text-xs">/llms.txt</code> proxies to this endpoint,
            or reference it directly.
          </CardDescription>
        </CardHeader>
        <CardContent className="pb-4 space-y-2">
          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
              {LLMS_TXT_ENDPOINT}
            </code>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 shrink-0"
              onClick={() => {
                navigator.clipboard.writeText(LLMS_TXT_ENDPOINT);
                toast.success("URL copied");
              }}
            >
              <Copy className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" asChild>
              <a href={LLMS_TXT_ENDPOINT} target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5" />
              </a>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default AeoGeoTab;

